<script>
function brandIconTools(){return{iconTab:'basic',iconBusy:false,iconNotice:'',iconPreview:'',iconDarkPreview:'',iconPackageReady:@js($kit && ($kit->config['icon_package_fingerprint']??'')===\App\Services\Brand\BrandIconPackage::fingerprint($kit)),
async iconCanvas(source,maskable=false){const canvas=document.createElement('canvas');canvas.width=canvas.height=512;const ctx=canvas.getContext('2d'),shape=maskable?'square':this.form.icon_shape;ctx.clearRect(0,0,512,512);if(shape!=='transparent'){ctx.fillStyle=this.form.icon_background||'#ffffff';if(this.form.icon_background_mode==='gradient'){const gradient=ctx.createLinearGradient(0,0,512,512);gradient.addColorStop(0,this.form.icon_background||'#ffffff');gradient.addColorStop(1,this.form.icon_background_end||'#8b5cf6');ctx.fillStyle=gradient;}ctx.beginPath();if(shape==='circle')ctx.arc(256,256,256,0,Math.PI*2);else if(shape==='rounded')ctx.roundRect(0,0,512,512,100);else ctx.rect(0,0,512,512);ctx.fill();ctx.clip();}const padding=Math.max(maskable?22:0,Number(this.form.icon_padding)||0)*512/100;const size=512-padding*2;
if(this.form.icon_source==='initials'&&!source){ctx.fillStyle=this.form.primary||'#3454ef';ctx.font='bold '+Math.round(size*.48)+'px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText((this.form.icon_initials||this.form.name||'B').slice(0,3).toUpperCase(),256,268,size);}else{if(!source)throw Error('Choose a logo or favicon first.');const image=new Image();image.crossOrigin='anonymous';await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('This image URL cannot be exported by the browser. Upload it or choose My Files instead.'));image.src=source;});if(image.naturalWidth<96)this.iconNotice='Small source image: use a larger logo for sharper app icons.';const scale=Math.min(size/image.naturalWidth,size/image.naturalHeight)*(maskable?Math.min(100,Number(this.form.icon_scale)||100):(Number(this.form.icon_scale)||100))/100;ctx.filter='brightness('+(Number(this.form.icon_brightness)||100)+'%)';ctx.drawImage(image,(512-image.naturalWidth*scale)/2+(maskable?0:Number(this.form.icon_x)||0)*5.12,(512-image.naturalHeight*scale)/2+(maskable?0:Number(this.form.icon_y)||0)*5.12,image.naturalWidth*scale,image.naturalHeight*scale);}
return canvas;},
iconSource(){return this.form.icon_source==='initials'?'':(this.form.icon_source==='favicon'?this.form.favicon:this.form.logo)},
async previewIcon(){this.iconBusy=true;this.iconNotice='';try{this.iconPreview=(await this.iconCanvas(this.iconSource())).toDataURL('image/png');this.iconDarkPreview=(await this.iconCanvas(this.form.icon_dark||this.iconSource())).toDataURL('image/png')}catch(e){this.iconNotice=e.message}finally{this.iconBusy=false}},
async generateIcons(){const url=@js($kit && Route::has('user.brand-kits.icons.generate')?route('user.brand-kits.icons.generate',$kit):null);if(!url||this.iconBusy)return;this.iconBusy=true;this.iconNotice='';try{const body=new FormData();body.append('fingerprint',@js($kit?\App\Services\Brand\BrandIconPackage::fingerprint($kit):''));for(const variant of ['main','dark','apple','android','maskable']){const source=variant==='dark'?(this.form.icon_dark||this.iconSource()):variant==='apple'?(this.form.icon_apple||this.iconSource()):(variant==='android'||variant==='maskable')?(this.form.icon_android||this.iconSource()):this.iconSource();const canvas=await this.iconCanvas(source,variant==='maskable');if(variant==='main')this.iconPreview=canvas.toDataURL();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Could not create this icon. Upload the source to My Files and try again.');body.append(variant,blob,variant+'.png');}const response=await fetch(url,{method:'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body});const data=await response.json();if(!response.ok)throw Error(data.message||'Could not save icons.');this.iconPackageReady=true;this.iconNotice=data.message;}catch(e){this.iconNotice=e.message}finally{this.iconBusy=false}}
}}
</script>
